import { createEffect, createSignal, ErrorBoundary, onCleanup, resetErrorBoundaries, Show, } from "solid-js";
import { createStore } from "solid-js/store";
import { Portal } from "solid-js/web";
import { Toolbar } from "terracotta";
import info from "../../../package.json" with { type: "json" };
import clientOnly from "../clientOnly.js";
import { HttpStatusCode } from "../HttpStatusCode.js";
import IconButton from "../ui/IconButton.jsx";
import { Text } from "../ui/Text.jsx";
import { ServerFunctionViewer } from "./functions/index.jsx";
import { captureServerFunctionCall } from "./functions/tracker.js";
import { ErrorIcon, FunctionIcon, SolidStartIcon } from "./icons.jsx";
import "./index.css";
const ErrorViewer = import.meta.env.PROD
    ? () => <></>
    : clientOnly(() => import("./error-viewer/index.jsx"), { lazy: true });
export function DevToolbar(props) {
    const [ref, setRef] = createSignal();
    createEffect(() => {
        const current = ref();
        if (current) {
            // Only the toolbar pill itself is the drag handle — panels/popovers are not draggable.
            const handle = current.querySelector(":scope > [tc-toolbar]") ?? current;
            let isDown = false;
            // Offsets of the mouse relatively to the element's position
            let offsetX = 0;
            let offsetY = 0;
            let currentX = 0;
            let currentY = 0;
            let centerX = 0;
            let centerY = 0;
            const resetPosition = () => {
                current.style.top = "auto";
                current.style.left = "auto";
                current.style.bottom = "auto";
                current.style.right = "auto";
            };
            let isDirty = false;
            const ac = new AbortController();
            handle.addEventListener("mousedown", e => {
                isDown = true;
                const rect = current.getBoundingClientRect();
                currentX = rect.left;
                currentY = rect.top;
                offsetX = e.clientX - currentX;
                offsetY = e.clientY - currentY;
                centerX = rect.width / 2;
                centerY = rect.height / 2;
                isDirty = true;
            }, {
                signal: ac.signal,
            });
            window.addEventListener("mouseup", () => {
                if (isDown && !isDirty) {
                    const preferredAnchorX = currentX + centerX < window.innerWidth / 2 ? "left" : "right";
                    const preferredAnchorY = currentY + centerY < window.innerHeight / 2 ? "top" : "bottom";
                    resetPosition();
                    current.style[preferredAnchorX] = "0px";
                    current.style[preferredAnchorY] = "0px";
                    current.style.flexDirection =
                        preferredAnchorY === "bottom" ? "column-reverse" : "column";
                    current.style.alignItems = preferredAnchorX === "left" ? "flex-start" : "flex-end";
                }
                isDown = false;
            }, {
                signal: ac.signal,
            });
            window.addEventListener("mousemove", e => {
                if (isDown) {
                    if (isDirty) {
                        resetPosition();
                        isDirty = false;
                    }
                    currentX = e.clientX - offsetX;
                    currentY = e.clientY - offsetY;
                    current.style.left = `${currentX}px`;
                    current.style.top = `${currentY}px`;
                }
            }, {
                signal: ac.signal,
                passive: true,
            });
            onCleanup(() => {
                ac.abort();
            });
        }
    });
    const [content, setContent] = createSignal(undefined);
    function toggleContent(value) {
        if (content() === value) {
            setContent(undefined);
        }
        else {
            setContent(value);
        }
    }
    const [errors, setErrors] = createSignal([]);
    function resetError() {
        setErrors([]);
        resetErrorBoundaries();
    }
    function pushError(error) {
        console.error(error);
        setErrors(current => [error, ...current]);
        setContent("err");
    }
    createEffect(() => {
        const onErrorEvent = (error) => {
            // Browsers dispatch benign ResizeObserver loop notifications as window
            // "error" events carrying no error object. They aren't app errors.
            if (!error.error && error.message?.startsWith("ResizeObserver loop")) {
                return;
            }
            pushError(error.error ?? error);
        };
        const onRejectionEvent = (event) => {
            pushError(event.reason);
        };
        window.addEventListener("error", onErrorEvent);
        window.addEventListener("unhandledrejection", onRejectionEvent);
        onCleanup(() => {
            window.removeEventListener("error", onErrorEvent);
            window.removeEventListener("unhandledrejection", onRejectionEvent);
        });
    });
    const [store, setStore] = createStore({
        instances: {},
    });
    createEffect(() => {
        onCleanup(captureServerFunctionCall(call => {
            if (call.type === "request") {
                setStore("instances", call.instance, value => {
                    return {
                        ...value,
                        request: call,
                    };
                });
            }
            else {
                setStore("instances", call.instance, value => {
                    return {
                        ...value,
                        response: call,
                    };
                });
            }
        }));
    });
    return (<>
      <Portal>
        <div data-start-dev-toolbar ref={setRef}>
          <Toolbar>
            <div>
              <IconButton onClick={() => toggleContent("err")} disabled={errors().length === 0}>
                <ErrorIcon title="View Errors"/>
              </IconButton>
              <IconButton onClick={() => toggleContent("fn")}>
                <FunctionIcon title="View Server Functions"/>
              </IconButton>
            </div>
            <div>
              <SolidStartIcon title="Solid Start Version"/>
              <div data-start-dev-toolbar-version>
                <Text options={{ size: "xs", weight: "semibold", font: "mono", wrap: "nowrap" }}>
                  {info.version}
                </Text>
              </div>
            </div>
          </Toolbar>
          <ErrorViewer show={content() === "err"} errors={errors()} resetError={resetError}/>
          <ServerFunctionViewer show={content() === "fn"} instances={store.instances} onDeleteInstance={value => {
            setStore("instances", value, undefined);
        }}/>
        </div>
      </Portal>
      <ErrorBoundary fallback={error => {
            pushError(error);
            return <HttpStatusCode code={500}/>;
        }}>
        {props.children}
      </ErrorBoundary>
      <Show when={errors().length > 0}>
        <HttpStatusCode code={500}/>
      </Show>
    </>);
}
